%[text] ![](text:image:1f7b)
clear
hmmm = [110, 111, 114, 105, 117, 32, 118, 97, 108, 103, 121, 116, 105];
hmmm_konvertuota = num2cell(hmmm) %[output:3783aee2]
cellfun(@isempty, hmmm_konvertuota) %[output:20204069]
%%
%[text] ![](text:image:51a8)
clear

m = input('Įrašyk eilučių skaičių "m": ') %[output:03078266]
n = input('Įrašyk stulpelių skaičių "n": ') %[output:5f86e971]

while(m ~= n) %[output:group:0d1b2b72]
    for eil = 1:m
        for stulp = 1:n
            mat(eil, stulp) = eil + stulp^2;
        end
    end
    surf(mat)
    m = input('Įrašyk eilučių skaičių "m": ') %[output:4683dd29]
    n = input('Įrašyk stulpelių skaičių "n": ') %[output:84405e32]
    mat = zeros(m, n);
    if(m==n)
        disp('Matricos eiluciu ir stulpeliu skaicius sutampa.') %[output:1d84f326]
    end
end %[output:group:0d1b2b72]
%%
%[text] ![](text:image:2fa5)
clear
clc

tarp_sk_tarp_zodziu_daugiau_nei_du = 1;
kiek_tarp_pas = 0;

while tarp_sk_tarp_zodziu_daugiau_nei_du

    sak = input("Įvesk sakinį taip, kad tarpai būtų sudaryti iš daugiau nei 2-jų tarpų: ", "s");
    kur_tarpas = isspace(sak);

    k_k_p_t_is_eiles = 0;
    kiek_tarp_pas = 0;
    tinkamas = 0;

    i = 1;

    while i <= length(kur_tarpas)

        if kur_tarpas(i) == 1

            k_k_p_t_is_eiles = 0;

            for j = i:length(kur_tarpas)

                if kur_tarpas(j)
                    k_k_p_t_is_eiles = k_k_p_t_is_eiles + 1;
                else
                    break
                end

            end

            if k_k_p_t_is_eiles > 1

                tarp_sk = k_k_p_t_is_eiles - 1;
                kiek_tarp_pas = kiek_tarp_pas + tarp_sk;
                tinkamas = 1;

                sak(i+1:i+k_k_p_t_is_eiles-1) = [];
                kur_tarpas = isspace(sak);

            end

        end

        i = i + 1;

    end

    if tinkamas == 1
        tarp_sk_tarp_zodziu_daugiau_nei_du = 0;
    else
        disp("Sakinys netinkamas. Įveskite dar kartą.")
    end

end

fprintf("Įvestas sakinys buvo tinkamas, redagavome jį pašalindami %d tarpų.\n", kiek_tarp_pas) %[output:08daba73]
disp(sak) %[output:8e33cd57]

